<?php

declare(strict_types=1);

namespace CodeClubLuxembourg\Sb3Toolkit\Builder\Blocks;

use CodeClubLuxembourg\Sb3Toolkit\Builder\Block;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Field\GreaterThanMenu;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Field\Key;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Input;

/**
 * Typed factories for Scratch "Events" blocks.
 *
 * Generated by bin/generate-blocks.php — do not edit by hand.
 */
final class Events
{
    public static function whenFlagClicked(): Block
    {
        return Block::make('event_whenflagclicked');
    }

    public static function whenKeyPressed(Key $keyOption): Block
    {
        return Block::make('event_whenkeypressed')
            ->field('KEY_OPTION', $keyOption->value);
    }

    public static function whenStageClicked(): Block
    {
        return Block::make('event_whenstageclicked');
    }

    public static function whenSpriteClicked(): Block
    {
        return Block::make('event_whenspriteclicked');
    }

    public static function whenBroadcastReceived(string $broadcastOption): Block
    {
        return Block::make('event_whenbroadcastreceived')
            ->field('BROADCAST_OPTION', $broadcastOption);
    }

    public static function whenBackdropSwitchesTo(string $backdrop): Block
    {
        return Block::make('event_whenbackdropswitchesto')
            ->field('BACKDROP', $backdrop);
    }

    public static function whenGreaterThan(int|float|Block|Input $value, GreaterThanMenu $whengreaterthanmenu): Block
    {
        return Block::make('event_whengreaterthan')
            ->input('VALUE', $value)
            ->field('WHENGREATERTHANMENU', $whengreaterthanmenu->value);
    }

    public static function broadcast(string|Block $broadcastInput): Block
    {
        return Block::make('event_broadcast')
            ->input('BROADCAST_INPUT', Input::menu('event_broadcast_menu', 'BROADCAST_OPTION', $broadcastInput));
    }

    public static function broadcastAndWait(string|Block $broadcastInput): Block
    {
        return Block::make('event_broadcastandwait')
            ->input('BROADCAST_INPUT', Input::menu('event_broadcast_menu', 'BROADCAST_OPTION', $broadcastInput));
    }
}
